// RR Turbo copy of the unit file (export_descr_unit_turbo.txt).
//
// RR Turbo (full mode) makes the game read <name>_turbo.txt instead of <name>.txt. In the RIS repo the
// _turbo copies are generated by _tools/_Tarnholm-tools/turbo-files/make_turbo_files.py from
// turbo_rules.py - the Turbo copy must never be a plain copy of the normal file, or the Turbo-only
// rules are lost. Manipula's Export writes this copy next to the normal EDU, so both files go into the
// mod together.
//
// TURBO_EDU_RULES mirrors every rule in turbo_rules.py whose file is EDU (kind "in_blocks"). Keep the
// two in step: a rule added there must be added here. make_turbo_files.py --check in the RIS repo
// reports OUT OF DATE if they ever differ.

const TURBO_EDU_RULES = [
  {
    why: "AI recruits AOR units at half priority (-100 -> -50); factional units stay preferred",
    block: "type",
    namePrefix: "aor ",
    find: "recruit_priority_offset -100",
    replace: "recruit_priority_offset -50",
    expect: [400, 600],
  },
];

// Same as make_turbo_files.in_blocks: `find` -> `replace` only inside blocks whose first line starts
// with `block` (e.g. "type") and whose name (the rest of that line) starts with `namePrefix`.
function inBlocks(text, nl, r) {
  const lines = text.split(nl);
  let n = 0;
  let inside = false;
  for (let i = 0; i < lines.length; i++) {
    const line = lines[i];
    const m = line.match(/^\s*(\S+)(?:\s+([\s\S]*))?$/);
    if (m && m[1] === r.block) {
      inside = m[2] !== undefined && m[2].trim().startsWith(r.namePrefix);
      continue;
    }
    if (inside && line.includes(r.find)) {
      n += line.split(r.find).length - 1;
      lines[i] = line.split(r.find).join(r.replace);
    }
  }
  return { text: lines.join(nl), n };
}

// Returns { text, report } where report lists each rule with its match count and whether the count
// is in the rule's expected range.
function makeTurboEdu(eduText) {
  const nl = eduText.includes("\r\n") ? "\r\n" : "\n";
  let text = eduText;
  const report = [];
  for (const r of TURBO_EDU_RULES) {
    const res = inBlocks(text, nl, r);
    text = res.text;
    const [lo, hi] = r.expect;
    report.push({ why: r.why, matches: res.n, ok: res.n >= lo && res.n <= hi });
  }
  return { text, report };
}

// "export_descr_unit" -> "export_descr_unit_turbo"; null for names that are not the unit file.
function turboBaseName(baseName) {
  const b = baseName || "export_descr_unit";
  return b === "export_descr_unit" ? "export_descr_unit_turbo" : null;
}

module.exports = { TURBO_EDU_RULES, inBlocks, makeTurboEdu, turboBaseName };
